namespace sv_51bdc134f14d46439eb3db64c69f65c9.Services;

/// <summary>
/// Holds the currently selected warehouse for a single circuit (user session).
/// Registered as scoped so each Blazor Server circuit gets its own instance.
/// </summary>
public sealed class WarehouseStateService
{
    public static readonly IReadOnlyList<(string Id, string Name)> AvailableWarehouses =
    [
        ("WH-A", "Warehouse A"),
        ("WH-B", "Warehouse B"),
        ("WH-C", "Warehouse C"),
        ("WH-D", "Warehouse D"),
    ];

    private string _currentWarehouseId = AvailableWarehouses[0].Id;

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        AvailableWarehouses.First(w => w.Id == _currentWarehouseId).Name;

    /// <summary>
    /// Fired when the selected warehouse changes.
    /// Subscribers must marshal back to their own synchronization context.
    /// </summary>
    public event Func<Task>? OnChange;

    public async Task SetWarehouseAsync(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId)
            return;

        _currentWarehouseId = warehouseId;

        if (OnChange is not null)
            await OnChange.Invoke();
    }
}

namespace sv_51bdc134f14d46439eb3db64c69f65c9.Services;

/// <summary>
/// Polls for low-stock alerts on a timer and notifies all subscribers.
/// Scoped per circuit so each user has independent alert state and polling.
/// </summary>
public sealed class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int LatestLowStockCount { get; private set; }

    /// <summary>
    /// Raised whenever fresh alert data arrives.
    /// All subscribed components receive this, not just the one that triggered polling.
    /// </summary>
    public event Func<int, Task>? OnAlertCountChanged;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += HandleWarehouseChangedAsync;
    }

    /// <summary>Simulates a database query returning a random low-stock count.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Call when a component that needs polling becomes active.
    /// Polling starts on the first subscriber and stops when the last unsubscribes.
    /// </summary>
    public void StartPolling()
    {
        _subscriberCount++;

        if (_subscriberCount == 1)
            BeginPollingLoop();
    }

    /// <summary>
    /// Call when a component that needs polling is disposed / leaves the page.
    /// </summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);

        if (_subscriberCount == 0)
            CancelPollingLoop();
    }

    private void BeginPollingLoop()
    {
        CancelPollingLoop();

        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));

        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fetch immediately on start, then every 10 seconds.
        await FetchAndNotifyAsync();

        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                await FetchAndNotifyAsync();
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on cancellation.
        }
    }

    private async Task FetchAndNotifyAsync()
    {
        LatestLowStockCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);

        if (OnAlertCountChanged is not null)
            await OnAlertCountChanged.Invoke(LatestLowStockCount);
    }

    private async Task HandleWarehouseChangedAsync()
    {
        if (_subscriberCount > 0)
            await FetchAndNotifyAsync();
    }

    private void CancelPollingLoop()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= HandleWarehouseChangedAsync;
        CancelPollingLoop();
    }
}

