@using sv_51bdc134f14d46439eb3db64c69f65c9.Services
@rendermode InteractiveServer
@implements IDisposable
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService

<PageTitle>Dashboard - @WarehouseState.CurrentWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title text-muted">Current Warehouse</h5>
                <p class="display-6">@WarehouseState.CurrentWarehouseName</p>
                <small class="text-muted">ID: @WarehouseState.CurrentWarehouseId</small>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card @(_lowStockCount > 5 ? "border-danger" : "border-success")">
            <div class="card-body text-center">
                <h5 class="card-title text-muted">Low Stock Alerts</h5>
                <p class="display-6 @(_lowStockCount > 5 ? "text-danger" : "text-success")">
                    @_lowStockCount
                </p>
                <small class="text-muted">Items below minimum level</small>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title text-muted">Polling Status</h5>
                <p class="display-6">
                    <span class="badge bg-success">Active</span>
                </p>
                <small class="text-muted">Refreshes every 10 seconds</small>
            </div>
        </div>
    </div>
</div>

<div class="mt-4">
    <small class="text-muted">Last updated: @_lastUpdated.ToString("HH:mm:ss")</small>
